"""The README must be generated by the tool, not by optimism.

Every headline number in the worked case is re-run here and must appear verbatim in the
rationale. Documentation drifting away from behaviour is the failure mode this catches.
"""

import json
import unittest
from pathlib import Path

from precision_dose import engine

ROOT = Path(__file__).resolve().parents[1]
README = (ROOT / "README.md").read_text(encoding="utf-8")
PATIENT = json.loads((ROOT / "demo" / "case_vanc.json").read_text())


def worked_case_lines():
    blocks = README.split("### Adding measured levels")[0].split("```")
    block = next(b for b in blocks if "Question: Vancomycin regimen" in b)
    prefixes = (
        "Individual parameters:",
        "Regimen:",
        "Predicted steady-state exposure:",
        "Probability of target attainment:",
        "Safety:",
    )
    return [ln.strip() for ln in block.splitlines() if ln.strip().startswith(prefixes)]


class TestReadmeMatchesBehaviour(unittest.TestCase):
    def test_headline_lines_reproduce(self):
        lines = worked_case_lines()
        self.assertGreaterEqual(len(lines), 4, "worked case block not found in README")
        res = engine.run_dose(PATIENT, "vancomycin", pta_n=5000)
        rationale = res["rationale"]
        for line in lines:
            self.assertIn(line, rationale, f"README is stale: {line}")

    def test_validation_table_matches(self):
        from precision_dose import validation

        rows = validation.run_cases()
        self.assertTrue(all(r["passed"] for r in rows))
        self.assertIn(f"{len(rows)}/{len(rows)} cases passed", README)

    def test_keywords_present(self):
        required = [
            "model-informed precision dosing (MIPD)",
            "Bayesian dose optimization",
            "therapeutic drug monitoring (TDM)",
            "pharmacometrics",
            "population pharmacokinetics",
            "clinical decision support (CDS)",
            "HL7 FHIR",
            "CYP450",
            "eGFR",
            "Child-Pugh",
            "pharmacogenomics (CPIC)",
            "drug-drug interactions (DDI)",
            "probability of target attainment (PTA)",
        ]
        flat = " ".join(README.split())  # the terms wrap across lines
        for term in required:
            self.assertIn(term, flat, term)


if __name__ == "__main__":
    unittest.main()
